 THEN RAISE EXCEPTION 'geography_destination_review_required';END IF;
 IF c->>'precision' IS DISTINCT FROM 'source_published'
 OR jsonb_typeof(c->'latitude') IS DISTINCT FROM 'number' OR jsonb_typeof(c->'longitude') IS DISTINCT FROM 'number'
 OR jsonb_typeof(b->'south') IS DISTINCT FROM 'number' OR jsonb_typeof(b->'north') IS DISTINCT FROM 'number'
 OR jsonb_typeof(b->'west') IS DISTINCT FROM 'number' OR jsonb_typeof(b->'east') IS DISTINCT FROM 'number'
 OR coalesce(b->>'source_url','')!~'^https://[^/:?#@]+/' THEN RAISE EXCEPTION 'geography_locality_evidence_required';END IF;
 lat:=(c->>'latitude')::double precision;lng:=(c->>'longitude')::double precision;
 south:=(b->>'south')::double precision;north:=(b->>'north')::double precision;
 west:=(b->>'west')::double precision;east:=(b->>'east')::double precision;
 IF south< -90 OR north>90 OR west< -180 OR east>180 OR south>=north OR west>=east
 OR north-south>5 OR east-west>5 OR lat<south OR lat>north OR lng<west OR lng>east OR(lat=0 AND lng=0)
 THEN RAISE EXCEPTION 'geography_outside_reviewed_locality';END IF;
 IF NOT zoi.geography_read_source_allowed(l) THEN RAISE EXCEPTION 'geography_source_authority_held';END IF;
 INSERT INTO zoi.geography_read_authority_epochs(listing_id) VALUES(l.id) ON CONFLICT(listing_id) DO NOTHING;
 before_geo:=jsonb_build_object('latitude',l.latitude,'longitude',l.longitude,'geo_precision',l.geo_precision,
 'profile_was_null',l.profile IS NULL,'had_geo',coalesce(l.profile,'{}'::jsonb)?'_geo','geo',l.profile->'_geo');
 IF place_proof IS NOT NULL THEN place_before:=l;place_geo:=jsonb_build_object('precision','street','method','reviewed_official_place_destination','evidence_kind','reviewed_official_place_destination','source_url',report->>'source_url','source_sha256',report->>'source_sha256','report_sha256',report_hash,'reviewer',p_review->>'reviewer','reviewed_at',review_time,'request_id',p_request,'place_proof_sha256',p_review->>'place_proof_sha256','source_job_id',place_job.id,'place_id',c->>'place_id','contact_card_sha256',place_proof#>>'{card,sha256}','source_link_occurrence_sha256',place_proof#>>'{selected,sha256}');END IF;
 UPDATE zoi.listings SET latitude=lat,longitude=lng,geo_precision='street',
 profile=coalesce(l.profile,'{}'::jsonb)||jsonb_build_object('_geo',CASE WHEN place_proof IS NOT NULL THEN place_geo ELSE jsonb_build_object(
 'precision','street','method','reviewed_official_source','source_url',report->>'source_url',
 'source_sha256',report->>'source_sha256','report_sha256',report_hash,'reviewer',p_review->>'reviewer',
 'reviewed_at',review_time,'request_id',p_request)END),updated_at=clock_timestamp()
 WHERE id=p_listing RETURNING * INTO l;
 IF place_proof IS NOT NULL AND(NOT FOUND OR to_jsonb(l)IS DISTINCT FROM(to_jsonb(place_before)||jsonb_build_object('latitude',lat,'longitude',lng,'geo_precision','street','profile',coalesce(place_before.profile,'{}'::jsonb)||jsonb_build_object('_geo',place_geo),'updated_at',transaction_timestamp()))OR(SELECT to_jsonb(actual_row)FROM zoi.listings actual_row WHERE actual_row.id=p_listing)IS DISTINCT FROM to_jsonb(l))THEN RAISE EXCEPTION 'geography_place_unexpected_listing_change';END IF;
 receipt:=jsonb_build_object('ok',true,'request_id',p_request,'listing_id',p_listing,
 'latitude',l.latitude,'longitude',l.longitude,'precision',l.geo_precision,'report_sha256',report_hash,
 'after_snapshot',zoi.geography_fingerprint(l));
 IF NOT zoi.geography_read_source_allowed(l) THEN RAISE EXCEPTION 'geography_source_authority_held';END IF;
 INSERT INTO zoi.geography_reviews(request_id,listing_id,payload,receipt,before_geo,after_fingerprint,read_authority_fingerprint)
 VALUES(p_request,p_listing,payload,receipt,before_geo,zoi.geography_fingerprint(l),zoi.geography_read_authority_fingerprint(l));
 RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION zoi.geography_url_component(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO ''
AS $function$
DECLARE b bytea:=''::bytea; i integer:=1; ch text;
BEGIN
 WHILE i<=length(p_text) LOOP
  ch:=substr(p_text,i,1);
  IF ch='%' THEN
   IF substr(p_text,i+1,2)!~'^[0-9A-Fa-f]{2}$' THEN RAISE EXCEPTION 'invalid_destination_encoding';END IF;
   b:=b||decode(substr(p_text,i+1,2),'hex');i:=i+3;
  ELSE b:=b||convert_to(CASE WHEN ch='+' THEN ' ' ELSE ch END,'UTF8');i:=i+1;END IF;
 END LOOP;
 RETURN convert_from(b,'UTF8');
END $function$

CREATE OR REPLACE FUNCTION zoi.auto_seo_fill()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_cat_slug text;
  v_cat_label text;
  v_slug text;
  v_title text;
  v_desc text;
BEGIN
  IF NEW.primary_category_id IS NOT NULL THEN
    SELECT c.slug, c.label_en INTO v_cat_slug, v_cat_label
    FROM zoi.categories c WHERE c.id = NEW.primary_category_id;
  END IF;

  v_slug := coalesce(NEW.slug, zoi.seo_slug(NEW.name || '-' || coalesce(NEW.city,'')));

  IF NEW.schema_type IS NULL OR length(NEW.schema_type)=0 THEN
    NEW.schema_type := zoi.schema_type(NEW.entity_type, coalesce(v_cat_slug,''));
  END IF;

  IF NEW.canonical_path IS NULL OR length(NEW.canonical_path)=0 THEN
    NEW.canonical_path := '/' || NEW.entity_type || '/' || v_slug;
  END IF;

  IF NEW.meta_title IS NULL OR length(NEW.meta_title)=0 THEN
    v_title := NEW.name
      || coalesce(' — ' || zoi.seo_pluralize(v_cat_label), '')
      || coalesce(' in ' || NEW.city, '')
      || ' | Zoi';
    IF length(v_title) > 66 THEN
      v_title := NEW.name || coalesce(' in ' || NEW.city, '') || ' | Zoi';
    END IF;
    IF length(v_title) > 66 THEN
      v_title := left(NEW.name, 60) || ' | Zoi';
    END IF;
    NEW.meta_title := v_title;
  END IF;

  IF NEW.meta_description IS NULL OR length(NEW.meta_description)=0 THEN
    IF NEW.description IS NOT NULL AND length(NEW.description) >= 30
       AND NEW.description !~* '^https?://' THEN
      v_desc := left(NEW.description, 158);
    ELSE
      v_desc := NEW.name
        || coalesce(' in ' || NEW.city, '')
        || coalesce(', ' || NEW.country, '')
        || '. Listed on Zoi, the Greek community directory.';
    END IF;
    NEW.meta_description := v_desc;
  END IF;

  RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION zoi.geography_source_enqueue_one(l zoi.listings, p_strategy text, p_generation bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE input_hash text;affected integer;authority_hash text;state text;why text;BEGIN
 IF p_strategy NOT IN('official_sources_v1','publisher_profiles_v1')OR p_generation<0 THEN RAISE EXCEPTION 'invalid_continuous_source_strategy';END IF;
 IF NOT zoi.geography_source_eligible(l) THEN RETURN 0;END IF;
 -- The deferred listing hook runs after the guarded writer's receipt insert.
 -- A fresh accepted street point is resolved, not another crawl opportunity.
 IF public.geography_reviewed_point(l.id) IS NOT NULL THEN RETURN 0;END IF;
 IF p_strategy='publisher_profiles_v1'AND(nullif(btrim(l.website),'')IS NOT NULL OR zoi.geography_publisher_host(l.source_url)IS NULL) THEN RETURN 0;END IF;
 input_hash:=zoi.geography_repair_strategy_input(l,p_strategy);authority_hash:=zoi.geography_source_authority_input(l);
 -- Do not lock or rewrite existing jobs while a listing write holds its row.
 -- This avoids reversing the worker's job->listing lock order.
 IF EXISTS(SELECT 1 FROM zoi.geography_repair_jobs j WHERE j.listing_id=l.id AND j.strategy=p_strategy AND j.input_fingerprint=input_hash AND j.source_generation=p_generation) THEN RETURN 0;END IF;
 state:=CASE WHEN zoi.geography_publisher_held(l) THEN 'source_blocked' WHEN p_strategy='publisher_profiles_v1' THEN 'queued' WHEN nullif(btrim(l.address),'')IS NULL THEN 'needs_address' WHEN l.website IS NULL OR l.website!~'^https://' THEN 'needs_source' ELSE 'queued' END;
 why:=CASE WHEN zoi.geography_publisher_held(l) THEN 'source_hold_preserved' WHEN p_strategy='publisher_profiles_v1' THEN 'individual_supporting_publisher_source_requires_research' WHEN state='needs_address' THEN 'public_address_requires_research' WHEN state='needs_source' THEN 'official_source_requires_identification' ELSE 'registered_source_requires_identity_address_coordinate_research' END;
 INSERT INTO zoi.geography_repair_jobs(listing_id,strategy,input_fingerprint,database_snapshot,idempotency_key,status,original,reason,source_generation,source_authority_fingerprint)
 VALUES(l.id,p_strategy,input_hash,zoi.geography_fingerprint(l),md5(l.id::text||'|'||p_strategy||'|'||input_hash||'|generation:'||p_generation::text),state,
 jsonb_build_object('name',l.name,'slug',l.slug,'entity_type',l.entity_type,'address',l.address,'city',l.city,'country',l.country,'website',l.website,'source_url',l.source_url,'source_kind',CASE WHEN p_strategy='publisher_profiles_v1' THEN 'supporting_publisher_profile' ELSE 'official_website' END,'source_host',zoi.geography_publisher_host(l.source_url),'latitude',l.latitude,'longitude',l.longitude,'precision',l.geo_precision,'metadata',l.profile->'_geo','profile',jsonb_build_object('_enrich',jsonb_build_object('blocked_reason',l.profile#>'{_enrich,blocked_reason}','scope_review_required',l.profile#>'{_enrich,scope_review_required}','organization_identity_quarantine',l.profile#>'{_enrich,organization_identity_quarantine}'))),why,p_generation,authority_hash)
 ON CONFLICT(listing_id,strategy,input_fingerprint,source_generation) DO NOTHING;
 GET DIAGNOSTICS affected=ROW_COUNT;RETURN affected;
END $function$

