CREATE OR REPLACE FUNCTION zoi.geography_place_anchor_href(anchor text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE at integer:=3;total integer:=length(anchor);key text;value text;quote text;keys text[]:='{}';href text;char text;m text[];start_at integer;BEGIN
 IF octet_length(anchor)>4096 OR anchor!~*'^<a[[:space:]>]'OR anchor!~*'</a[[:space:]]*>$'OR anchor~*'<!--|<(script|style|noscript|template|svg)[[:space:]>]|<a[[:space:]>].*<a[[:space:]>]'THEN RAISE EXCEPTION 'geography_place_anchor_invalid';END IF;
 LOOP
 WHILE at<=total AND substring(anchor FROM at FOR 1)~'[[:space:]]'LOOP at:=at+1;END LOOP;EXIT WHEN substring(anchor FROM at FOR 1)='>';
 m:=regexp_match(substring(anchor FROM at),'^([^[:space:]=<>"''`/]+)');IF m IS NULL THEN RAISE EXCEPTION 'geography_place_anchor_invalid';END IF;key:=lower(m[1]);IF key=ANY(keys)THEN RAISE EXCEPTION 'geography_place_anchor_invalid';END IF;keys:=array_append(keys,key);at:=at+length(m[1]);
 WHILE at<=total AND substring(anchor FROM at FOR 1)~'[[:space:]]'LOOP at:=at+1;END LOOP;value:='';
 IF substring(anchor FROM at FOR 1)='='THEN at:=at+1;WHILE at<=total AND substring(anchor FROM at FOR 1)~'[[:space:]]'LOOP at:=at+1;END LOOP;quote:=substring(anchor FROM at FOR 1);IF quote NOT IN('"',chr(39))THEN RAISE EXCEPTION 'geography_place_anchor_invalid';END IF;at:=at+1;start_at:=at;
 LOOP IF at>total THEN RAISE EXCEPTION 'geography_place_anchor_invalid';END IF;EXIT WHEN substring(anchor FROM at FOR 1)=quote;at:=at+1;END LOOP;value:=zoi.geography_place_html_decode(substring(anchor FROM start_at FOR at-start_at));at:=at+1;END IF;
 IF key='href'THEN href:=value;END IF;
 IF key='hidden'OR(key='aria-hidden'AND value='true')OR(key='style'AND value~*'display[[:space:]]*:[[:space:]]*none|visibility[[:space:]]*:[[:space:]]*hidden')THEN RAISE EXCEPTION 'geography_place_anchor_invalid';END IF;
 END LOOP;
 IF href IS NULL OR at>total THEN RAISE EXCEPTION 'geography_place_anchor_invalid';END IF;RETURN href;
END $function$

CREATE OR REPLACE FUNCTION zoi.geography_place_quote(card bytea, quote jsonb, literal text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE start_at integer;end_at integer;raw text;visible text;BEGIN
 IF jsonb_typeof(quote)IS DISTINCT FROM 'object'OR jsonb_typeof(quote->'start_byte')IS DISTINCT FROM 'number'OR jsonb_typeof(quote->'end_byte')IS DISTINCT FROM 'number'OR coalesce(quote->>'start_byte','')!~'^[0-9]+$'OR coalesce(quote->>'end_byte','')!~'^[0-9]+$'OR nullif(zoi.geography_place_norm(literal),'')IS NULL THEN RETURN false;END IF;
 start_at:=(quote->>'start_byte')::integer;end_at:=(quote->>'end_byte')::integer;IF start_at<0 OR end_at<=start_at OR end_at>octet_length(card)THEN RETURN false;END IF;
 raw:=convert_from(substring(card FROM start_at+1 FOR end_at-start_at),'UTF8');visible:=zoi.geography_place_norm(zoi.geography_place_html_decode(regexp_replace(raw,'<[^>]*>',' ','g')));
 RETURN encode(extensions.digest(convert_to(raw,'UTF8'),'sha256'),'hex')IS NOT DISTINCT FROM quote->>'sha256'AND strpos(' '||visible||' ',' '||zoi.geography_place_norm(literal)||' ')>0;
END $function$

CREATE OR REPLACE FUNCTION zoi.publish_gate(p_name text, p_entity_type text, p_category bigint, p_city text, p_country text, p_phone text, p_address text, p_website text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_name  text := coalesce(btrim(p_name),'');
  v_alpha text;
  v_et    text := lower(coalesce(btrim(p_entity_type),''));
  v_fails text[] := array[]::text[];
  v_warn  text[] := array[]::text[];
  v_lq    jsonb;
  v_physical boolean;
  v_any_channel boolean;
BEGIN
  v_alpha := regexp_replace(v_name,'[^[:alpha:]]','','g');
  -- Entity types that exist at a physical place. Creators, vendors (online shops),
  -- artists and travel listings are legitimately location-less.
  v_physical := v_et IN ('business','church','school','venue','sports','professional');
  v_any_channel := coalesce(btrim(p_website),'') <> ''
                OR coalesce(btrim(p_phone),'')   <> ''
                OR coalesce(btrim(p_address),'') <> '';

  -- 1. NAME INTEGRITY
  IF v_name = '' THEN v_fails := array_append(v_fails,'name_empty'); END IF;
  IF length(v_alpha) < 2 THEN v_fails := array_append(v_fails,'name_no_real_letters'); END IF;
  IF length(v_name) > 120 THEN v_fails := array_append(v_fails,'name_too_long'); END IF;

  -- 2. SCRAPE ARTEFACTS
  -- Listicle: "Top 10 Best ..." — number must be followed by a word, so "Best 92.6" (radio) is safe.
  IF v_name ~* '(^|[^[:alpha:]])(top|best)[[:space:]]+[0-9]{1,3}[[:space:]]+[[:alpha:]]' THEN
    v_fails := array_append(v_fails,'listicle_title');
  END IF;
  IF v_name ~* '(yelp|tripadvisor|wikipedia|google maps|facebook\.com|instagram\.com|linkedin\.com)' THEN
    v_fails := array_append(v_fails,'platform_title');
  END IF;
  IF v_name ~* 'near me$|^the [0-9]+ (best|top) |updated [0-9]{4}|^[0-9]+ (best|top) ' THEN
    v_fails := array_append(v_fails,'seo_title');
  END IF;
  -- Pipe alone is NOT junk (real names like "Astra Report | WNTN 1550 AM" exist).
  -- Only flag a trailing " - <platform>" or " | <platform>" suffix.
  IF v_name ~* '[[:space:]][-|][[:space:]]*(yelp|tripadvisor|facebook|instagram|menu|home|official site)[[:space:]]*$' THEN
    v_fails := array_append(v_fails,'page_title_artefact');
  END IF;
  IF lower(v_name) ~ '^(home|about|about us|contact|contact us|menu|untitled|test|n/?a|null|none|unknown|tbd|click here|read more|business directory)$' THEN
    v_fails := array_append(v_fails,'nav_or_placeholder_name');
  END IF;

  -- 3. CLASSIFICATION
  IF p_category IS NULL THEN v_fails := array_append(v_fails,'missing_category'); END IF;

  -- 4. LOCATION — only required for physical entity types, and only when there is
  -- also no contact channel to identify the entity by.
  IF v_physical
     AND coalesce(btrim(p_city),'') = ''
     AND coalesce(btrim(p_country),'') = ''
     AND NOT v_any_channel THEN
    v_fails := array_append(v_fails,'no_location_and_no_contact');
  END IF;

  -- 5. Existing scorer's hard-junk judgement
  v_lq := zoi.listing_quality(p_name,p_phone,p_address,p_website,p_category,p_entity_type);
  IF (v_lq->>'ok')::boolean IS FALSE THEN
    v_fails := array_append(v_fails,'listing_quality_fail');
  END IF;

  -- 6. WARNINGS — never block; these feed the enrichment queue.
  IF NOT v_any_channel THEN v_warn := array_append(v_warn,'no_contact_channel'); END IF;
  IF coalesce(btrim(p_city),'')='' THEN v_warn := array_append(v_warn,'no_city'); END IF;
  IF coalesce(btrim(p_country),'')='' THEN v_warn := array_append(v_warn,'no_country'); END IF;

  RETURN jsonb_build_object(
    'ok', (array_length(v_fails,1) IS NULL),
    'fails', to_jsonb(v_fails),
    'warnings', to_jsonb(v_warn),
    'quality_score', (v_lq->>'score')::int
  );
END;
$function$

CREATE OR REPLACE FUNCTION zoi.tg_apply_publish_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_gate jsonb;
begin
 if new.publish_status is null or new.publish_status in ('draft','published') then
  v_gate:=zoi.publish_gate(new.name,new.entity_type,new.primary_category_id,new.city,new.country,new.phone,new.address,new.website);
  if new.publish_status is distinct from 'draft' then
   if (v_gate->>'ok')::boolean then new.publish_status:='published';
   else new.publish_status:='pending_review';end if;
  end if;
  new.profile:=coalesce(new.profile,'{}'::jsonb)||jsonb_build_object('gate',jsonb_build_object(
   'ok',v_gate->'ok','fails',v_gate->'fails','warnings',v_gate->'warnings',
   'checked_at',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')));
  new.completeness_score:=round(((v_gate->>'quality_score')::numeric/100.0),3);
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION zoi.guard_listing_quality_receipts()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE prior_receipt jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN prior_receipt:=OLD.profile->'_coverage';END IF;
 IF (current_user IN('anon','authenticated') OR current_setting('request.jwt.claim.role',true) IN('anon','authenticated') OR coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb->>'role' IN('anon','authenticated')) AND NEW.profile->'_coverage' IS DISTINCT FROM prior_receipt THEN RAISE EXCEPTION 'quality_receipts_service_only';END IF;
 RETURN NEW;
