CREATE OR REPLACE FUNCTION public.geography_review_revert(p_request uuid, p_expected text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r zoi.geography_reviews;l zoi.listings;
BEGIN
 IF p_request IS NULL OR p_expected IS NULL THEN RAISE EXCEPTION 'invalid_geography_review';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('geography-review:'||p_request::text,0));
 SELECT * INTO r FROM zoi.geography_reviews WHERE request_id=p_request;
 IF NOT FOUND THEN RAISE EXCEPTION 'geography_review_missing';END IF;
 SELECT * INTO l FROM zoi.listings WHERE id=r.listing_id FOR UPDATE;
 IF NOT FOUND OR l.owner_user_id IS NOT NULL OR l.owner_workspace_id IS NOT NULL
 THEN RAISE EXCEPTION 'geography_listing_unavailable';END IF;
 IF r.reverted_at IS NOT NULL THEN RETURN jsonb_build_object('ok',true,'reverted',true,'request_id',p_request);END IF;
 IF p_expected IS DISTINCT FROM r.after_fingerprint OR zoi.geography_fingerprint(l) IS DISTINCT FROM r.after_fingerprint
 THEN RAISE EXCEPTION 'geography_snapshot_changed';END IF;
 UPDATE zoi.listings SET latitude=(r.before_geo->>'latitude')::double precision,
 longitude=(r.before_geo->>'longitude')::double precision,geo_precision=r.before_geo->>'geo_precision',
 profile=CASE WHEN r.before_geo->'profile_was_null'='true'::jsonb THEN NULL WHEN r.before_geo->'had_geo'='true'::jsonb THEN jsonb_set(coalesce(l.profile,'{}'::jsonb),'{_geo}',r.before_geo->'geo') ELSE coalesce(l.profile,'{}'::jsonb)-'_geo' END,
 updated_at=clock_timestamp() WHERE id=r.listing_id;
 UPDATE zoi.geography_reviews SET reverted_at=clock_timestamp() WHERE request_id=p_request;
 RETURN jsonb_build_object('ok',true,'reverted',true,'request_id',p_request);
END $function$

CREATE OR REPLACE FUNCTION zoi.seo_name(p_name text, p_city text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE n text:=zoi.seo_text(p_name); c text:=zoi.seo_text(p_city);
BEGIN
 IF c<>'' AND pg_catalog.length(n)>pg_catalog.length(c)+1 AND pg_catalog.right(n,pg_catalog.length(c)+1)=' '||c THEN
  RETURN pg_catalog.left(n,pg_catalog.length(n)-pg_catalog.length(c)-1);
 END IF;
 RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION zoi.geography_place_html_decode(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE result text:='';remaining text:=value;m text[];prefix text;entity text;n bigint;BEGIN
 IF value IS NULL OR octet_length(value)>8192 THEN RAISE EXCEPTION 'geography_place_html_invalid';END IF;
 LOOP m:=regexp_match(remaining,'(&amp;|&quot;|&apos;|&nbsp;|&lt;|&gt;|&#[0-9]+;|&#x[0-9a-f]+;)','i');EXIT WHEN m IS NULL;
 entity:=m[1];prefix:=split_part(remaining,entity,1);result:=result||prefix;
 IF lower(entity)IN('&amp;','&quot;','&apos;','&nbsp;','&lt;','&gt;')THEN result:=result||CASE lower(entity)WHEN '&amp;'THEN '&'WHEN '&quot;'THEN '"'WHEN '&apos;'THEN chr(39)WHEN '&nbsp;'THEN ' 'WHEN '&lt;'THEN '<'ELSE '>'END;
 ELSE IF lower(left(entity,3))='&#x'THEN IF length(entity)>12 THEN RAISE EXCEPTION 'geography_place_html_invalid';END IF;n:=('x'||lpad(substring(entity FROM 4 FOR length(entity)-4),8,'0'))::bit(32)::bigint;ELSE n:=substring(entity FROM 3 FOR length(entity)-3)::bigint;END IF;
 IF n<1 OR n>1114111 OR n BETWEEN 55296 AND 57343 THEN RAISE EXCEPTION 'geography_place_html_invalid';END IF;result:=result||chr(n::integer);END IF;
 remaining:=substring(remaining FROM length(prefix)+length(entity)+1);
 END LOOP;RETURN result||remaining;
END $function$

CREATE OR REPLACE FUNCTION zoi.listing_quality(p_name text, p_phone text, p_address text, p_website text, p_category bigint, p_entity_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_score int := 60;
  v_reasons text[] := array[]::text[];
  v_name text := coalesce(btrim(p_name), '');
  v_phone text := coalesce(btrim(p_phone), '');
  v_addr text := coalesce(btrim(p_address), '');
  v_web text := coalesce(btrim(p_website), '');
  v_et text := lower(coalesce(btrim(p_entity_type), ''));
  v_tokens int; v_alpha text;
  v_has_contact boolean; v_any_channel boolean;
  v_is_person boolean; v_needs_physical boolean;
  v_biz_token boolean; v_looks_personal boolean; v_allcaps_surname boolean;
  v_identifiable boolean; v_hard_junk boolean := false;
  v_threshold int := 55;
begin
  v_alpha := regexp_replace(v_name, '[^[:alpha:]]', '', 'g');
  v_tokens := array_length(regexp_split_to_array(v_name, '\s+'), 1);
  if v_name = '' then v_tokens := 0; end if;

  v_is_person := v_et in ('professional','creator','artist');
  v_needs_physical := v_et in ('business','church','school','venue','organization','sports');

  v_biz_token := v_name ~* '(restaurant|taverna|taverne|tavern|ouzeri|mezze?|meze|cuisine|cafe|caf[eé]|kafe|kafenio|coffee|bakery|patisserie|pastry|pastries|grill|kitchen|kouzina|koyzina|estiatorio|psistaria|deli|market|bazaar|grocery|foods?|seafood|diner|pita|gardens|honey|farm|mastiha|apothecary|magazine|bar|bistro|pizz|gyro|souvlaki|club|hotel|inn|resort|room|studio|salon|spa|clinic|center|centre|institute|academy|school|college|church|kirche|orthodox|cathedral|parish|monastery|temple|shrine|theotokos|annunciation|dormition|nativity|ascension|assumption|transfiguration|filoptochos|brotherhood|pancyprian|associat|society|federation|foundation|council|union|chamber|company|co\.|corp|inc\.?|ltd|llc|gmbh|group|network|television|world|services|solutions|consult|agency|law|legal|medical|dental|pharmac|insurance|realty|real estate|travel|tours|imports|exports|trading|wines|winery|brewery|distillery|productions|media|radio|fm|tv|ert|gallery|museum|theatre|theater|festival|function|expo|games|fc|f\.c\.|football|soccer|hellenic|greek|grecian|hellas|athenian|mitilini|parthenon|delfini|myth|casa|saint|st\.|holy|cosmos|concept|grove|olive|blue)';

  -- ALLCAPS "SURNAME FIRSTNAME" Greek scrape junk (the named hard pattern)
  v_allcaps_surname := (not v_biz_token) and v_tokens between 2 and 3
    and v_name = upper(v_name) and v_name ~ '^[[:upper:]]{2,}([[:space:]\-]+[[:upper:]]{2,}){1,2}$';
  -- Titlecase personal-name shape: SOFT signal only (too many brand collisions)
  v_looks_personal := (not v_biz_token) and v_tokens between 2 and 3
    and v_name ~ '^[[:upper:]][[:lower:]]+([[:space:]\-]+[[:upper:]][[:lower:]]+){1,2}$';

  v_has_contact := (v_phone <> '' or v_addr <> '');
  v_any_channel := (v_phone <> '' or v_addr <> '' or v_web <> '');

  v_identifiable := v_any_channel or v_biz_token or (coalesce(v_tokens,0) >= 2) or v_is_person;

  -- HARD JUNK NAME CHECKS
  if v_name = '' then
    v_score := 0; v_hard_junk := true; v_reasons := array_append(v_reasons, 'name_empty'::text);
  elsif v_name ~ '^[0-9[:space:][:punct:]]+$' then
    v_score := 0; v_hard_junk := true; v_reasons := array_append(v_reasons, 'name_digits_or_symbols_only'::text);
  elsif length(v_alpha) < 2 then
    v_score := 0; v_hard_junk := true; v_reasons := array_append(v_reasons, 'name_no_real_letters'::text);
  elsif v_tokens = 1 and length(v_name) <= 3 and not v_any_channel then
    -- single very short token AND no way to find it = junk; with contact it's identifiable
    v_score := v_score - 40; v_hard_junk := true;
    v_reasons := array_append(v_reasons, 'name_single_short_token_no_contact'::text);
  end if;

  -- BUSINESS as bare ALLCAPS personal name with NO contact = junk (named pattern)
  if v_et = 'business' and v_allcaps_surname and not v_any_channel then
    v_score := v_score - 50; v_hard_junk := true;
    v_reasons := array_append(v_reasons, 'business_allcaps_personal_name_no_contact'::text);
  end if;

  -- SOFT SIGNALS
  if v_phone <> '' then v_score := v_score + 10; v_reasons := array_append(v_reasons, 'has_phone'::text); end if;
  if v_addr  <> '' then v_score := v_score + 10; v_reasons := array_append(v_reasons, 'has_address'::text); end if;
  if v_web   <> '' then v_score := v_score + 8;  v_reasons := array_append(v_reasons, 'has_website'::text); end if;
  if v_biz_token  then v_score := v_score + 5;  v_reasons := array_append(v_reasons, 'has_business_keyword'::text); end if;

  -- Titlecase personal-name business with no contact: soft warning only
  if v_et = 'business' and v_looks_personal and not v_any_channel then
    v_reasons := array_append(v_reasons, 'business_name_may_be_personal'::text);
  end if;

  if p_category is not null then
    v_score := v_score + 8; v_reasons := array_append(v_reasons, 'has_category'::text);
  else
    v_score := v_score - 6; v_reasons := array_append(v_reasons, 'missing_category'::text);
  end if;

  if not v_has_contact then
    if v_is_person then
      v_reasons := array_append(v_reasons, 'person_no_physical_contact_ok'::text);
    elsif v_web <> '' then
      v_score := v_score - 4; v_reasons := array_append(v_reasons, 'no_phone_or_address_website_only'::text);
    else
      v_score := v_score - 8; v_reasons := array_append(v_reasons, 'thin_contact_needs_enrichment'::text);
    end if;
  end if;

  -- FLOOR: identifiable, non-junk listings stay published despite incompleteness
  if not v_hard_junk and v_identifiable and v_score < v_threshold then
    v_score := v_threshold;
  end if;

  if v_score < 0 then v_score := 0; end if;
  if v_score > 100 then v_score := 100; end if;

  return jsonb_build_object(
    'score', v_score, 'ok', (v_score >= v_threshold),
    'threshold', v_threshold, 'reasons', to_jsonb(v_reasons));
end;
$function$

CREATE OR REPLACE FUNCTION zoi.geography_source_listing_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l zoi.listings;generation bigint;previous zoi.geography_repair_jobs;became_unowned_public boolean:=false;current_hash text;authority_hash text;BEGIN
 -- Deferred events must use the final row, not an intermediate NEW snapshot.
 SELECT * INTO l FROM zoi.listings WHERE id=NEW.id;
 IF l.id IS NULL OR NOT zoi.geography_source_eligible(l) OR public.geography_reviewed_point(l.id) IS NOT NULL THEN RETURN NULL;END IF;
 IF TG_OP='UPDATE' THEN became_unowned_public:=OLD.owner_user_id IS NOT NULL OR OLD.owner_workspace_id IS NOT NULL OR OLD.publish_status IS DISTINCT FROM 'published' OR (OLD.moderation_status IS DISTINCT FROM 'clean' AND OLD.moderation_status IS DISTINCT FROM 'cleared') OR OLD.marketplace_status='hidden';END IF;
 current_hash:=zoi.geography_repair_input(l);authority_hash:=zoi.geography_source_authority_input(l);generation:=zoi.geography_source_generation(l.id);
 SELECT * INTO previous FROM zoi.geography_repair_jobs WHERE listing_id=l.id AND strategy='official_sources_v1'AND source_generation=generation ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT coalesce(became_unowned_public,false) AND previous.id IS NOT NULL AND previous.input_fingerprint=current_hash AND(previous.source_authority_fingerprint=authority_hash OR(previous.source_authority_fingerprint=''AND(TG_OP='INSERT'OR zoi.geography_source_authority_input(OLD)=authority_hash)))THEN
  -- Same final input/generation: terminal history does not cause endless retries.
  -- Still add a missing supporting lane idempotently when appropriate.
  PERFORM zoi.geography_source_enqueue_one(l,'publisher_profiles_v1',generation);RETURN NULL;
 END IF;
 generation:=generation+1;
 PERFORM zoi.geography_source_enqueue_one(l,'official_sources_v1',generation);
 PERFORM zoi.geography_source_enqueue_one(l,'publisher_profiles_v1',generation);
 RETURN NULL;
END $function$
